-- =====================================================================
-- Agentic SalesMan -- 300 sample catalog rows (100 phone / 100 laptop /
-- 100 headphone), matching the schema BACKEND/DATABASE/SQL_CONNECTOR.py
-- and TOOLS/product_tools.py expect.
--
-- Base columns (name, brand, price, processor/type, ram/quality,
-- storage, color) are what the sales-agent RAG pipeline already reads
-- today. The extra columns (mrp, units_available, rating, online_link,
-- offline_availability) are OPTIONAL enrichments picked up automatically
-- by WORKFLOW/recommendations.py + WORKFLOW/scoring.py when present --
-- they're what unlocks the discount %, stock count, "Buy Online" link
-- and offline-availability line on the frontend's Buy Now card, plus the
-- rating component of the recommendation score (see scoring.py's
-- RATING_COLUMN_NAMES / WORKFLOW/recommendations.py's *_COLUMNS lists).
-- `online_link` values below are PLACEHOLDER URLs (your-store.example)
-- -- replace them with real product URLs before this goes anywhere near
-- real customers.
--
-- Usage:
--   1. If your `phone`/`laptop`/`headphone` tables don't exist yet, the
--      CREATE TABLE IF NOT EXISTS blocks below create them.
--   2. If they already exist (this looks like your case -- your chat
--      already returns real phone/laptop/headphone results), run just
--      the ALTER TABLE block to add the optional enrichment columns.
--      MySQL will error with "Duplicate column name" for any column you
--      already have -- that's harmless, just delete that one line and
--      re-run the rest.
--   3. Then run the INSERT statements. After they land, restart the
--      backend once (or delete WORKFLOW/chroma_db/) so the row-count
--      sync in SQL_CONNECTOR.py notices the new rows and re-embeds them
--      into Chroma -- otherwise the RAG store keeps using the old data.
--
--   mysql -u <username> -p retail_shop < sample_data_300.sql
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. Tables (safe no-op if they already exist)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS phone (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    name                VARCHAR(255) NOT NULL,
    brand               VARCHAR(100) NOT NULL,
    price               INT NOT NULL,
    mrp                 INT NULL,
    processor           VARCHAR(100) NULL,
    ram                 VARCHAR(20) NULL,
    storage             VARCHAR(20) NULL,
    color               VARCHAR(50) NULL,
    units_available     INT NULL,
    rating              DECIMAL(2,1) NULL,
    online_link         VARCHAR(500) NULL,
    offline_availability VARCHAR(255) NULL
);

CREATE TABLE IF NOT EXISTS laptop (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    name                VARCHAR(255) NOT NULL,
    brand               VARCHAR(100) NOT NULL,
    price               INT NOT NULL,
    mrp                 INT NULL,
    processor           VARCHAR(100) NULL,
    ram                 VARCHAR(20) NULL,
    storage             VARCHAR(20) NULL,
    color               VARCHAR(50) NULL,
    units_available     INT NULL,
    rating              DECIMAL(2,1) NULL,
    online_link         VARCHAR(500) NULL,
    offline_availability VARCHAR(255) NULL
);

CREATE TABLE IF NOT EXISTS headphone (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    name                VARCHAR(255) NOT NULL,
    brand               VARCHAR(100) NOT NULL,
    price               INT NOT NULL,
    mrp                 INT NULL,
    type                VARCHAR(100) NULL,
    quality             VARCHAR(100) NULL,
    color               VARCHAR(50) NULL,
    units_available     INT NULL,
    rating              DECIMAL(2,1) NULL,
    online_link         VARCHAR(500) NULL,
    offline_availability VARCHAR(255) NULL
);

-- ---------------------------------------------------------------------
-- 2. Optional enrichment columns for EXISTING tables that only have the
--    base columns today (delete any single line MySQL calls a duplicate)
-- ---------------------------------------------------------------------
ALTER TABLE phone     ADD COLUMN mrp INT NULL, ADD COLUMN units_available INT NULL, ADD COLUMN rating DECIMAL(2,1) NULL, ADD COLUMN online_link VARCHAR(500) NULL, ADD COLUMN offline_availability VARCHAR(255) NULL;
ALTER TABLE laptop    ADD COLUMN mrp INT NULL, ADD COLUMN units_available INT NULL, ADD COLUMN rating DECIMAL(2,1) NULL, ADD COLUMN online_link VARCHAR(500) NULL, ADD COLUMN offline_availability VARCHAR(255) NULL;
ALTER TABLE headphone ADD COLUMN mrp INT NULL, ADD COLUMN units_available INT NULL, ADD COLUMN rating DECIMAL(2,1) NULL, ADD COLUMN online_link VARCHAR(500) NULL, ADD COLUMN offline_availability VARCHAR(255) NULL;

-- ---------------------------------------------------------------------
-- 3. Seed data -- 100 rows per table, 300 total
-- ---------------------------------------------------------------------
